#include <iostream>

// Returns a safe reference to a persistent static variable
int& getCounter() {
    static int counter = 0;
    ++counter;
    return counter;
}

// Demonstrates const reference for inspection without copy overhead
void printValue(const int& val) {
    std::cout << "Value via const ref: " << val << "\n";
}

int main() {
    int original = 42;
    int& alias = original; // Local alias

    std::cout << "original: " << original << ", alias: " << alias << "\n";
    alias = 99; // Modifies original
    std::cout << "after alias modification -> original: " << original << "\n";

    // Test const reference with an lvalue and temporary
    printValue(original);
    printValue(100 + 23); // Const ref can bind to a temporary rvalue

    // Safe reference return demonstration
    int& refCount = getCounter();
    std::cout << "Counter initial: " << refCount << "\n";
    refCount = 10; // Directly updates the internal static counter
    std::cout << "Counter after external update: " << getCounter() << "\n";

    return 0;
}

#include <iostream>

// Prototype specifying default arguments for length, width, and height
int boxVolume(int length = 1, int width = 1, int height = 1);

// Parameterless function: In C++, this takes strictly zero arguments
void showBanner();

int main() {
    showBanner();

    // 1. Call using all default values (1 * 1 * 1)
    std::cout << "Default volume: " << boxVolume() << "\n";

    // 2. Call specifying length only (10 * 1 * 1)
    std::cout << "Volume (10, default, default): " << boxVolume(10) << "\n";

    // 3. Call specifying length and width (10 * 5 * 1)
    std::cout << "Volume (10, 5, default): " << boxVolume(10, 5) << "\n";

    // 4. Call specifying all dimensions (10 * 5 * 2)
    std::cout << "Volume (10, 5, 2): " << boxVolume(10, 5, 2) << "\n";

    return 0;
}

void showBanner() {
    std::cout << "=== Box Volume Calculator ===\n";
}

// Definition: DO NOT repeat default argument values here
int boxVolume(int length, int width, int height) {
    return length * width * height;
}
